/**
 * 事件时间线文案翻译。
 *
 * 新数据：后端 title/description 存 i18n key（timeline.*），
 * 变量参数存 event_metadata；前端 t(key, metadata) 渲染。
 * 历史数据：旧行 title/description 是中文原文，不是 key，
 * te() 取不到时原样显示（不崩）。
 * 用户输入（注释 content、AI 分析文本、错误详情）保持原样不翻译。
 */
import i18n from '@/locales'

export interface TimelineEventLike {
  title?: string | null
  description?: string | null
  event_metadata?: Record<string, unknown> | null
}

export function timelineText(
  event: TimelineEventLike,
  field: 'title' | 'description'
): string {
  const value = event[field]
  if (!value) {
    return ''
  }
  // 仅 timeline.* 前缀才尝试翻译，避免误伤历史数据/用户输入
  if (!value.startsWith('timeline.')) {
    return value
  }
  if (!i18n.global.te(value)) {
    return value
  }
  const params = (event.event_metadata ?? {}) as Record<string, never>
  return i18n.global.t(value, params)
}
