import type { AnalysisJobRead } from '@/api/ai'

/** 自动分析任务状态 → Element Plus tag 类型。 */
export function analysisJobTagType(
  status: AnalysisJobRead['status']
): 'primary' | 'success' | 'warning' | 'danger' | 'info' {
  switch (status) {
    case 'pending':
      return 'warning'
    case 'running':
      return 'primary'
    case 'success':
      return 'success'
    case 'failed':
      return 'danger'
    case 'skipped':
      return 'info'
    default:
      return 'info'
  }
}

/** 任务是否处于进行中状态（需要轮询跟进）。 */
export function isAnalysisJobActive(job: AnalysisJobRead | null | undefined): boolean {
  return job?.status === 'pending' || job?.status === 'running'
}
