<template>
  <div v-if="incident" class="page-incident-detail">
    <div class="page-header">
      <h2>{{ t('incidents.detailTitle', { id: incident.id }) }}</h2>
      <div>
        <el-button @click="$router.back()">{{ t('common.back') }}</el-button>
        <el-button
          type="primary"
          :disabled="incident.status !== 'open'"
          @click="onAck"
        >
          {{ t('incidents.ack') }}
        </el-button>
        <el-button
          type="success"
          :disabled="incident.status === 'resolved' || incident.status === 'closed'"
          @click="onResolve"
        >
          {{ t('incidents.resolve') }}
        </el-button>
        <el-button
          type="info"
          :disabled="incident.status === 'closed'"
          @click="onClose"
        >
          {{ t('common.close') }}
        </el-button>
      </div>
    </div>

    <el-row :gutter="16">
      <el-col :span="16">
        <el-card>
          <template #header>
            <span>{{ t('incidents.detail.basicInfo') }}</span>
          </template>
          <el-descriptions :column="2" border>
            <el-descriptions-item :label="t('incidents.titleColumn')">{{ incident.title }}</el-descriptions-item>
            <el-descriptions-item :label="t('common.status')">
              <StatusTag :status="incident.status" type="incident" />
            </el-descriptions-item>
            <el-descriptions-item :label="t('common.severityLabel')">
              <StatusTag :status="incident.severity" type="severity" />
            </el-descriptions-item>
            <el-descriptions-item :label="t('incidents.detail.source')">{{ incident.source }}</el-descriptions-item>
            <el-descriptions-item :label="t('incidents.detail.node')">{{ incident.node_id || '-' }}</el-descriptions-item>
            <el-descriptions-item :label="t('incidents.assignee')">{{ incident.assigned_to || '-' }}</el-descriptions-item>
            <el-descriptions-item :label="t('incidents.startedAt')">{{ formatTime(incident.started_at) }}</el-descriptions-item>
            <el-descriptions-item :label="t('incidents.detail.createdAt')">{{ formatTime(incident.created_at) }}</el-descriptions-item>
          </el-descriptions>
          <div class="section-title">{{ t('incidents.detail.description') }}</div>
          <p style="white-space: pre-wrap; color: var(--el-text-color-regular)">
            {{ incident.description || t('incidents.detail.noDescription') }}
          </p>
        </el-card>

        <el-card style="margin-top: 16px">
          <template #header>
            <span>{{ t('incidents.detail.relatedAlerts') }}</span>
          </template>
          <el-table :data="incident.alerts" stripe :empty-text="t('incidents.detail.noRelatedAlerts')">
            <el-table-column prop="alert_event_id" :label="t('incidents.detail.alertEventId')" width="120" />
            <el-table-column prop="alert_event.message" :label="t('common.message')" min-width="200">
              <template #default="{ row }">
                {{ row.alert_event?.message || '-' }}
              </template>
            </el-table-column>
            <el-table-column prop="alert_event.severity" :label="t('common.severityLabel')" width="100">
              <template #default="{ row }">
                <StatusTag :status="row.alert_event?.severity || '-'" type="severity" />
              </template>
            </el-table-column>
            <el-table-column prop="added_at" :label="t('incidents.detail.addedAt')" min-width="160">
              <template #default="{ row }">
                {{ row.added_at ? formatTime(row.added_at) : '-' }}
              </template>
            </el-table-column>
          </el-table>
        </el-card>
      </el-col>

      <el-col :span="8">
        <el-card v-if="authStore.isAdmin">
          <template #header>
            <div class="card-header">
              <span>{{ t('incidents.detail.aiRootCause') }}</span>
              <el-button
                type="primary"
                size="small"
                :loading="analyzing"
                :disabled="aiExecuted"
                @click="onAnalyze"
              >
                {{ aiAnalysis ? t('incidents.detail.reanalyze') : t('incidents.detail.startAnalysis') }}
              </el-button>
            </div>
          </template>

          <div v-if="aiJob && aiJob.status !== 'success'" class="ai-job-status">
            <el-tag :type="analysisJobTagType(aiJob.status)" size="small">
              {{ t(`incidents.detail.aiJob.${aiJob.status}`) }}
            </el-tag>
            <span v-if="aiJob.reason" class="ai-job-reason">{{ aiJob.reason }}</span>
          </div>

          <div v-if="aiAnalysis">
            <div class="ai-section">
              <div class="ai-label">{{ t('incidents.detail.analysisLabel') }}</div>
              <div class="ai-content">{{ aiAnalysis.analysis || t('incidents.detail.none') }}</div>
            </div>
            <div class="ai-section">
              <div class="ai-label">{{ t('incidents.detail.confidence') }}</div>
              <el-tag :type="confidenceType(aiAnalysis.confidence)">
                {{ formatConfidence(aiAnalysis.confidence) }}
              </el-tag>
            </div>
            <div class="ai-section">
              <div class="ai-label">{{ t('incidents.detail.suggestedAction') }}</div>
              <div class="ai-content">
                {{ aiAnalysis.suggested_action || t('incidents.detail.noSuggestedAction') }}
              </div>
            </div>
            <div v-if="aiAnalysis.reasoning" class="ai-section">
              <div class="ai-label">{{ t('incidents.detail.reasoning') }}</div>
              <div class="ai-content">{{ aiAnalysis.reasoning }}</div>
            </div>

            <div v-if="!aiAnalysis.executed && aiAnalysis.suggested_action" class="ai-actions">
              <el-button type="success" size="small" @click="onExecuteAnalysis(true)">
                {{ t('incidents.detail.executeSuggested') }}
              </el-button>
              <el-button size="small" @click="onExecuteAnalysis(false)">
                {{ t('incidents.detail.ignore') }}
              </el-button>
            </div>
            <div v-else-if="aiAnalysis.executed" class="ai-executed">
              {{ t('incidents.detail.executed', { result: aiAnalysis.execution_result }) }}
            </div>
          </div>

          <el-empty
            v-else
            :description="
              isAnalysisJobActive(aiJob)
                ? t('incidents.detail.aiAutoRunningHint')
                : t('incidents.detail.aiEmptyHint')
            "
          />
        </el-card>

        <el-card style="margin-top: 16px">
          <template #header>
            <span>{{ t('incidents.detail.timeline') }}</span>
          </template>
          <el-timeline>
            <el-timeline-item
              v-for="event in timeline"
              :key="event.id"
              :timestamp="formatTime(event.timestamp)"
              :type="timelineItemType(event.event_type)"
            >
              <div class="timeline-title">{{ timelineText(event, 'title') }}</div>
              <div v-if="timelineText(event, 'description')" class="timeline-desc">
                {{ timelineText(event, 'description') }}
              </div>
              <div v-if="event.event_subtype" class="timeline-subtype">
                {{ event.event_subtype }}
              </div>
            </el-timeline-item>
          </el-timeline>
          <el-empty v-if="timeline.length === 0" :description="t('incidents.detail.noTimeline')" />
        </el-card>

        <el-card style="margin-top: 16px">
          <template #header>
            <span>{{ t('incidents.detail.addNote') }}</span>
          </template>
          <el-input
            v-model="noteContent"
            type="textarea"
            :rows="3"
            :placeholder="t('incidents.detail.notePlaceholder')"
          />
          <el-button type="primary" style="margin-top: 12px" @click="onAddNote">
            {{ t('incidents.detail.submitNote') }}
          </el-button>
        </el-card>
      </el-col>
    </el-row>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import {
  acknowledgeIncident,
  addIncidentNote,
  closeIncident,
  getIncident,
  getIncidentTimeline,
  resolveIncident,
  type IncidentDetailRead,
  type IncidentEventRead,
} from '@/api/incidents'
import {
  analyzeIncident,
  confirmAnalysis,
  getAnalysisJobStatus,
  type AIAnalysisRead,
  type AnalysisJobRead,
} from '@/api/ai'
import { useAuthStore } from '@/stores/auth'
import { useRealtimeRefresh } from '@/composables/useRealtimeRefresh'
import StatusTag from '@/components/common/StatusTag.vue'
import { analysisJobTagType, isAnalysisJobActive } from '@/utils/analysisJob'
import { showError } from '@/utils/error'
import { timelineText } from '@/utils/timelineText'

const { t } = useI18n()
const route = useRoute()
const incidentId = Number(route.params.id)
const authStore = useAuthStore()

const incident = ref<IncidentDetailRead | null>(null)
const timeline = ref<IncidentEventRead[]>([])
const noteContent = ref('')
const aiAnalysis = ref<AIAnalysisRead | null>(null)
const analyzing = ref(false)
const aiJob = ref<AnalysisJobRead | null>(null)

let jobPollTimer: ReturnType<typeof setTimeout> | undefined

function clearJobPoll() {
  if (jobPollTimer !== undefined) {
    clearTimeout(jobPollTimer)
    jobPollTimer = undefined
  }
}

async function loadAnalysisStatus() {
  if (!authStore.isAdmin) return
  try {
    const status = await getAnalysisJobStatus(incidentId)
    aiJob.value = status.job
    // 仅展示有实际分析文本的结果（失败记录的 analysis 为 null）
    if (status.analysis && status.analysis.analysis) {
      aiAnalysis.value = status.analysis
    }
  } catch {
    // 静默降级：License 未解锁（403）等场景不打扰主流程，零 console error
    aiJob.value = null
  } finally {
    clearJobPoll()
    // 排队中/分析中每 5s 轮询跟进，终态停止
    if (isAnalysisJobActive(aiJob.value)) {
      jobPollTimer = setTimeout(loadAnalysisStatus, 5000)
    }
  }
}

async function loadIncident() {
  try {
    incident.value = await getIncident(incidentId)
  } catch (error) {
    showError(error, t('incidents.detail.loadDetailFailed'))
  }
}

async function loadTimeline() {
  try {
    const events = await getIncidentTimeline(incidentId)
    timeline.value = events.slice().reverse()
  } catch (error) {
    showError(error, t('incidents.detail.loadTimelineFailed'))
  }
}

async function onAck() {
  try {
    await acknowledgeIncident(incidentId)
    ElMessage.success(t('incidents.acked'))
    refresh()
  } catch (error) {
    showError(error, t('incidents.ackFailed'))
  }
}

async function onResolve() {
  try {
    await resolveIncident(incidentId)
    ElMessage.success(t('incidents.resolved'))
    refresh()
  } catch (error) {
    showError(error, t('incidents.resolveFailed'))
  }
}

async function onClose() {
  try {
    await closeIncident(incidentId)
    ElMessage.success(t('incidents.closed'))
    refresh()
  } catch (error) {
    showError(error, t('incidents.closeFailed'))
  }
}

async function onAddNote() {
  if (!noteContent.value.trim()) {
    ElMessage.warning(t('incidents.detail.noteRequired'))
    return
  }
  try {
    await addIncidentNote(incidentId, { content: noteContent.value })
    ElMessage.success(t('incidents.detail.noteAdded'))
    noteContent.value = ''
    loadTimeline()
  } catch (error) {
    showError(error, t('incidents.detail.addNoteFailed'))
  }
}

function timelineItemType(eventType: string) {
  if (eventType.includes('created')) return 'danger'
  if (eventType.includes('acknowledged')) return 'warning'
  if (eventType.includes('resolved')) return 'success'
  if (eventType.includes('closed')) return 'info'
  return 'primary'
}

function formatTime(value: string) {
  return new Date(value).toLocaleString()
}

async function onAnalyze() {
  analyzing.value = true
  try {
    aiAnalysis.value = await analyzeIncident(incidentId)
    ElMessage.success(t('incidents.detail.aiAnalysisDone'))
    loadAnalysisStatus()
  } catch (error) {
    showError(error, t('incidents.detail.aiAnalysisFailed'))
  } finally {
    analyzing.value = false
  }
}

async function onExecuteAnalysis(execute: boolean) {
  if (!aiAnalysis.value) return
  try {
    const result = await confirmAnalysis(aiAnalysis.value.id, { execute })
    ElMessage.success(result.message)
    aiAnalysis.value = {
      ...aiAnalysis.value,
      executed: result.executed,
      execution_result: result.message,
      heal_task_id: result.task_id || null,
    }
    loadTimeline()
  } catch (error) {
    showError(error, execute ? t('incidents.detail.executeFailed') : t('incidents.detail.ignoreFailed'))
  }
}

function confidenceType(confidence: number | null | undefined) {
  if (confidence === null || confidence === undefined) return 'info'
  if (confidence >= 0.8) return 'success'
  if (confidence >= 0.5) return 'warning'
  return 'danger'
}

function formatConfidence(confidence: number | null | undefined) {
  if (confidence === null || confidence === undefined) return '-'
  return `${(confidence * 100).toFixed(0)}%`
}

const aiExecuted = computed(() => aiAnalysis.value?.executed === true)

async function refresh() {
  await loadIncident()
  await loadTimeline()
  await loadAnalysisStatus()
}

useRealtimeRefresh(refresh, ['incidents'])

onMounted(() => {
  refresh()
})

onUnmounted(() => {
  clearJobPoll()
})
</script>

